ALTER TABLE auth.users
    ADD COLUMN IF NOT EXISTS middle_name VARCHAR(255);

UPDATE auth.users
SET middle_name = CASE id
    WHEN '0268bbe0-0aee-419e-9765-10ef5f25ddd9' THEN 'Дмитриевич'
    WHEN '11111111-1111-4111-8111-111111111111' THEN 'Александрович'
    WHEN '22222222-2222-4222-8222-222222222222' THEN 'Сергеевна'
    WHEN '33333333-3333-4333-8333-333333333333' THEN 'Викторович'
    WHEN '44444444-4444-4444-8444-444444444444' THEN 'Николаевич'
    WHEN '55555555-5555-4555-8555-555555555555' THEN 'Павловна'
    WHEN '66666666-6666-4666-8666-666666666666' THEN 'Игоревна'
    WHEN '77777777-7777-4777-8777-777777777777' THEN 'Денисович'
    WHEN '88888888-8888-4888-8888-888888888888' THEN 'Андреевна'
    WHEN '99999999-9999-4999-8999-999999999999' THEN 'Олегович'
    WHEN 'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa' THEN 'Михайловна'
    ELSE middle_name
END
WHERE id IN (
    '0268bbe0-0aee-419e-9765-10ef5f25ddd9',
    '11111111-1111-4111-8111-111111111111',
    '22222222-2222-4222-8222-222222222222',
    '33333333-3333-4333-8333-333333333333',
    '44444444-4444-4444-8444-444444444444',
    '55555555-5555-4555-8555-555555555555',
    '66666666-6666-4666-8666-666666666666',
    '77777777-7777-4777-8777-777777777777',
    '88888888-8888-4888-8888-888888888888',
    '99999999-9999-4999-8999-999999999999',
    'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'
);
